INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Einmaligkeit nach DIN 69901 ein zwingendes Merkmal jedes Projekts?', 2, '[{"text": "Ja", "correct": true, "because": "Sie definiert ein Projekt"}, {"text": "Nein", "correct": false, "because": "Andere Merkmale reichen aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal betont die Einmaligkeit nach DIN 69901 am stärksten?', 3, '[{"text": "Zeitliche Befristung", "correct": false, "because": "Das ist ein anderes Merkmal"}, {"text": "Neuheit der Bedingungen", "correct": true, "because": "Einmaligkeit bedeutet Einzigartigkeit"}, {"text": "Feste Budgets", "correct": false, "because": "Das ist eine Begrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind wiederkehrende Aufgaben ein Projekt nach DIN 69901?', 2, '[{"text": "Nein", "correct": true, "because": "Einmaligkeit fehlt"}, {"text": "Ja", "correct": false, "because": "Routine ist kein Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingung ist für die Einmaligkeit nach DIN 69901 unerlässlich?', 3, '[{"text": "Wiederholbarkeit", "correct": false, "because": "Widerspricht der Einmaligkeit"}, {"text": "Zielvorgabe", "correct": true, "because": "Einmalige Ziele sind zentral"}, {"text": "Teamgröße", "correct": false, "because": "Irrelevant für Einmaligkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt nach DIN 69901 ohne Einmaligkeit existieren?', 2, '[{"text": "Nein", "correct": true, "because": "Einmaligkeit ist Kernmerkmal"}, {"text": "Ja", "correct": false, "because": "Es wäre kein Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Einmaligkeit nach DIN 69901 richtig? a) Sie bezieht sich auf die Gesamtheit der Bedingungen. b) Sie bedeutet identische Prozesse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht der Definition"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Einmaligkeit nach DIN 69901?', 4, '[{"text": "Sie grenzt Projekte von Prozessen ab", "correct": true, "because": "Prozesse sind wiederholbar"}, {"text": "Sie definiert die Kosten", "correct": false, "because": "Kosten sind separat"}, {"text": "Sie bestimmt die Teamzusammensetzung", "correct": false, "because": "Das ist unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein monatlicher Bericht ein Projekt nach DIN 69901?', 2, '[{"text": "Nein", "correct": true, "because": "Keine Einmaligkeit"}, {"text": "Ja", "correct": false, "because": "Es ist eine Routine"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bedeutet Einmaligkeit der Bedingungen nach DIN 69901?', 3, '[{"text": "Einzigartige Kombination von Faktoren", "correct": true, "because": "Das ist die Definition"}, {"text": "Wiederholbare Abläufe", "correct": false, "because": "Widerspricht Einmaligkeit"}, {"text": "Feste Zeitpläne", "correct": false, "because": "Das ist ein anderes Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt nach DIN 69901 standardisierte Abläufe haben?', 2, '[{"text": "Ja", "correct": true, "because": "Abläufe können standardisiert sein, Bedingungen nicht"}, {"text": "Nein", "correct": false, "because": "Einmaligkeit schließt das nicht aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Einmaligkeit nach DIN 69901?', 3, '[{"text": "Jährliche Steuererklärung", "correct": false, "because": "Wiederkehrend"}, {"text": "Neubau einer Brücke", "correct": true, "because": "Einmaliges Vorhaben"}, {"text": "Wöchentliche Teammeetings", "correct": false, "because": "Routine"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Einmaligkeit nach DIN 69901 korrekt? a) Sie unterscheidet Projekte von Routine. b) Sie erfordert feste Budgets.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist ein separates Merkmal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gehört nicht zur Einmaligkeit nach DIN 69901?', 4, '[{"text": "Zielvorgabe", "correct": false, "because": "Teil der Bedingungen"}, {"text": "Projektspezifische Organisation", "correct": false, "because": "Teil der Einmaligkeit"}, {"text": "Regelmäßige Wiederholung", "correct": true, "because": "Widerspricht Einmaligkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Softwareentwicklung eines Updates ein Projekt nach DIN 69901?', 2, '[{"text": "Ja", "correct": true, "because": "Einmalige Bedingungen"}, {"text": "Nein", "correct": false, "because": "Es erfüllt die Kriterien"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet ein Projekt nach DIN 69901 von einer Daueraufgabe?', 3, '[{"text": "Einmaligkeit der Bedingungen", "correct": true, "because": "Daueraufgaben sind wiederkehrend"}, {"text": "Teamgröße", "correct": false, "because": "Irrelevant"}, {"text": "Budgethöhe", "correct": false, "because": "Kein Unterscheidungsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt nach DIN 69901 mehrere Phasen haben?', 2, '[{"text": "Ja", "correct": true, "because": "Phasen ändern nichts an Einmaligkeit"}, {"text": "Nein", "correct": false, "because": "Phasen sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für die Einmaligkeit nach DIN 69901 entscheidend?', 3, '[{"text": "Abgrenzung zu anderen Vorhaben", "correct": true, "because": "Teil der Definition"}, {"text": "Feste Deadlines", "correct": false, "because": "Separates Merkmal"}, {"text": "Großes Team", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind wiederholbare Prozesse Teil der Einmaligkeit nach DIN 69901?', 2, '[{"text": "Nein", "correct": true, "because": "Einmaligkeit schließt Wiederholung aus"}, {"text": "Ja", "correct": false, "because": "Prozesse sind keine Projekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Projekt erfüllt die Einmaligkeit nach DIN 69901?', 4, '[{"text": "Tägliche Serverwartung", "correct": false, "because": "Routine"}, {"text": "Entwicklung einer neuen App", "correct": true, "because": "Einmalige Bedingungen"}, {"text": "Monatliche Inventur", "correct": false, "because": "Wiederkehrend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Einmaligkeit nach DIN 69901 nur auf das Ziel beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Sie umfasst alle Bedingungen"}, {"text": "Ja", "correct": false, "because": "Es geht um die Gesamtheit"}]');